#!/bin/bash
# Run ON THE DREAMHOST SERVER from the new site's web directory (e.g. ~/new.everettallenphotography.com).
# Copies resized (watermarked) photos from the WordPress uploads folder into ./photos/<gallery>/.
set -e
UP="${1:-$HOME/everettallenphotography.com/wp-content/uploads}"
[ -d "$UP/sunshine" ] || { echo "Uploads folder not found: $UP (pass it as the first argument)"; exit 1; }
mkdir -p photos assets
mkdir -p photos/2026-leather-at-twin-cities-pride
